/*
 * n8n Code node.
 * Input: one item containing ReportJson from dbo.GetShippedOrdersAnalytics.
 * Output:
 *   - json.html       HTML as text (for upload/publishing)
 *   - binary.report  ready report.html (for Telegram Send Document)
 */

const source = $json.ReportJson ?? $json.reportJson ?? $json.data ?? $json;

function parseDeep(value) {
  let current = value;
  for (let i = 0; i < 3 && typeof current === 'string'; i++) {
    current = JSON.parse(current);
  }
  return current;
}

const report = parseDeep(source);
const summary = report.Summary ?? {};
const reportVersion = '14';
const generatedAt = new Date();
const buildStamp = generatedAt.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'Z');
const outputFileName = `shipped-report_${report.DateFrom}_${report.DateTo}_${buildStamp}.html`;
const logoDataUri = 'data:image/svg+xml;base64,';

const rows = value => Array.isArray(value) ? value : [];
const money = value => new Intl.NumberFormat('uk-UA', {
  maximumFractionDigits: 0,
}).format(Number(value || 0));
const number = value => new Intl.NumberFormat('uk-UA', {
  maximumFractionDigits: 1,
}).format(Number(value || 0));
const date = value => {
  if (!value) return '—';
  const [year, month, day] = String(value).slice(0, 10).split('-');
  return `${day}.${month}.${year}`;
};
const escapeHtml = value => String(value ?? '—')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#039;');

const pct = (value, total) => total > 0 ? (Number(value || 0) * 100 / total) : 0;
const maxOf = (items, key) => Math.max(1, ...items.map(item => Number(item[key] || 0)));
const growth = value => {
  if (value === null || value === undefined || !Number.isFinite(Number(value))) {
    return '<span class="growth neutral">немає бази</span>';
  }
  const numeric = Number(value);
  const cls = numeric > 0 ? 'positive' : numeric < 0 ? 'negative' : 'neutral';
  const arrow = numeric > 0 ? '▲' : numeric < 0 ? '▼' : '•';
  return `<span class="growth ${cls}">${arrow} ${numeric > 0 ? '+' : ''}${number(numeric)}%</span>`;
};

function metric(label, value, note = '') {
  return `<article class="metric">
    <div class="metric-label">${escapeHtml(label)}</div>
    <div class="metric-value">${value}</div>
    ${note ? `<div class="metric-note">${note}</div>` : ''}
  </article>`;
}

function bars(items, valueKey, suffix = '') {
  const max = maxOf(items, valueKey);
  return items.map((item, index) => {
    const value = Number(item[valueKey] || 0);
    return `<div class="bar-row">
      <div class="bar-label" title="${escapeHtml(item.Name ?? item.ABC ?? item.Bucket ?? item.Date)}">
        ${escapeHtml(item.Name ?? item.ABC ?? item.Bucket ?? date(item.Date))}
      </div>
      <div class="bar-track"><div class="bar-fill c${index % 5}" style="width:${Math.max(2, value * 100 / max)}%"></div></div>
      <div class="bar-value">${money(value)}${suffix}</div>
    </div>`;
  }).join('');
}

function accordion(title, subtitle, body, open = false, id = '') {
  return `<details ${id ? `id="${escapeHtml(id)}"` : ''} ${open ? 'open' : ''}>
    <summary>
      <span>${escapeHtml(title)}</span>
      <small>${escapeHtml(subtitle)}</small>
      <i>›</i>
    </summary>
    <div class="detail-body">${body}</div>
  </details>`;
}

function growthChart(items) {
  const points = items.filter(item => Number.isFinite(Number(item.GrowthPercent)));
  if (!points.length) return '<div class="empty">Недостатньо даних для розрахунку приросту</div>';

  const width = 680;
  const height = 250;
  const padding = { top: 28, right: 18, bottom: 42, left: 46 };
  const plotWidth = width - padding.left - padding.right;
  const plotHeight = height - padding.top - padding.bottom;
  const maxAbs = Math.max(10, ...points.map(item => Math.abs(Number(item.GrowthPercent))));
  const zeroY = padding.top + plotHeight / 2;
  const scaleY = value => zeroY - (Number(value) / maxAbs) * (plotHeight / 2);
  const slot = plotWidth / points.length;
  const barWidth = Math.min(38, slot * 0.58);
  const scaleX = index => padding.left + index * slot + slot / 2;
  const gridValues = [maxAbs, maxAbs / 2, 0, -maxAbs / 2, -maxAbs];
  const grid = gridValues.map(value => {
    const y = scaleY(value);
    return `<line x1="${padding.left}" y1="${y}" x2="${width - padding.right}" y2="${y}" class="chart-grid ${value === 0 ? 'zero' : ''}"/>
      <text x="${padding.left - 7}" y="${y + 3}" class="chart-axis" text-anchor="end">${number(value)}%</text>`;
  }).join('');
  const coordinates = points.map((item, index) => ({
    item,
    value: Number(item.GrowthPercent),
    x: scaleX(index),
    y: scaleY(Number(item.GrowthPercent)),
  }));
  const linePoints = coordinates.map(point => `${point.x},${point.y}`).join(' ');
  const trendSvg = coordinates.map(({ item, value, x, y }) => {
    const labelY = value >= 0 ? y - 11 : y + 19;
    const month = monthLabel(item.Month).split(' ')[0];
    const barY = Math.min(zeroY, y);
    const barHeight = Math.max(2, Math.abs(zeroY - y));
    return `<g>
      <rect x="${x - barWidth / 2}" y="${barY}" width="${barWidth}" height="${barHeight}" rx="5" class="chart-bar ${value >= 0 ? 'up' : 'down'}"/>
      <text x="${x}" y="${labelY}" class="chart-value ${value >= 0 ? 'up-text' : 'down-text'}" text-anchor="middle">${value > 0 ? '+' : ''}${number(value)}%</text>
      <text x="${x}" y="${height - 15}" class="chart-month" text-anchor="middle">${month}</text>
    </g>`;
  }).join('');

  return `<div class="growth-chart"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Графік тренда приросту та падіння суми відвантажень за місяцями">
      ${grid}
      ${trendSvg}
      ${points.length > 1 ? `<polyline points="${linePoints}" class="chart-trend-line"/>` : ''}
      ${coordinates.map(({ value, x, y }) => `<circle cx="${x}" cy="${y}" r="6" class="chart-point ${value >= 0 ? 'up' : 'down'}"/><circle cx="${x}" cy="${y}" r="2.4" class="chart-point-core"/>`).join('')}
    </svg>
    <div class="chart-legend"><span><i class="legend-up"></i>Приріст</span><span><i class="legend-down"></i>Падіння</span></div>
  </div>`;
}

const trends = rows(report.DailyTrend);
const types = rows(report.ConstructionTypes);
const profiles = rows(report.ProfileSystems);
const furniture = rows(report.Furniture);
const colors = rows(report.Colors);
const abc = rows(report.ABC);
const timeliness = rows(report.ProductionTimeliness);
const contractors = rows(report.Contractors);
const orders = rows(report.Orders);
const years = rows(report.YearComparison);
const months = rows(report.MonthlyComparison);
const categoryMonths = rows(report.CategoryMonthlyComparison);
const contractorName = String(
  report.ContractorName
  ?? contractors[0]?.ContractorName
  ?? orders[0]?.ContractorName
  ?? 'Контрагент не знайдений'
).trim();

const monthLabel = value => {
  if (!value) return '—';
  const [year, month] = String(value).split('-');
  const labels = ['Січ', 'Лют', 'Бер', 'Квіт', 'Трав', 'Черв', 'Лип', 'Серп', 'Вер', 'Жовт', 'Лист', 'Груд'];
  return `${labels[Number(month) - 1]} ${year}`;
};

const reportYear = Number(String(report.DateTo).slice(0, 4));
const currentYearMonths = months.filter(item => Number(String(item.Month).slice(0, 4)) === reportYear);
const onTimeOrders = timeliness
  .filter(item => item.Bucket === 'Вчасно')
  .reduce((sum, item) => sum + Number(item.OrdersCount || 0), 0);
const lateOrders = timeliness
  .filter(item => ['+1 день', '+2–3 дні', '+4–7 днів', 'Понад 7 днів'].includes(item.Bucket))
  .reduce((sum, item) => sum + Number(item.OrdersCount || 0), 0);
const noProductionDateOrders = timeliness
  .filter(item => ['Немає дати готовності', 'Немає планової дати'].includes(item.Bucket))
  .reduce((sum, item) => sum + Number(item.OrdersCount || 0), 0);
const productionMeasured = onTimeOrders + lateOrders;
const onTimePercent = pct(onTimeOrders, productionMeasured);
const latePercent = pct(lateOrders, productionMeasured);
const productionCircle = 2 * Math.PI * 54;
const onTimeDash = productionMeasured ? productionCircle * onTimePercent / 100 : 0;
const lateDash = productionMeasured ? productionCircle * latePercent / 100 : 0;
const productionHero = `<section class="production-hero">
  <div class="production-title"><span>Дотримання строків виробництва</span><small>за замовленнями з відомими плановою та фактичною датами</small></div>
  <div class="production-chart">
    <svg viewBox="0 0 140 140" role="img" aria-label="Вчасно ${number(onTimePercent)} відсотка, невчасно ${number(latePercent)} відсотка">
      <circle class="production-ring-bg" cx="70" cy="70" r="54"/>
      <a href="#shipped-orders" onclick="document.getElementById('shipped-orders').open=true">
        <circle class="production-ring on-time clickable" cx="70" cy="70" r="54" stroke-dasharray="${onTimeDash} ${productionCircle - onTimeDash}"/>
      </a>
      <a href="#shipped-orders" onclick="document.getElementById('shipped-orders').open=true">
        <circle class="production-ring late clickable" cx="70" cy="70" r="54" stroke-dasharray="${lateDash} ${productionCircle - lateDash}" stroke-dashoffset="${-onTimeDash}"/>
      </a>
      <text x="70" y="65" text-anchor="middle" class="production-total">${money(productionMeasured)}</text>
      <text x="70" y="81" text-anchor="middle" class="production-total-label">замовлень</text>
    </svg>
  </div>
  <div class="production-stats">
    <a class="production-stat on-time" href="#shipped-orders" onclick="document.getElementById('shipped-orders').open=true"><i></i><div><span>Вчасно</span><strong>${money(onTimeOrders)}</strong><small>${number(onTimePercent)}%</small></div></a>
    <a class="production-stat late" href="#shipped-orders" onclick="document.getElementById('shipped-orders').open=true"><i></i><div><span>Невчасно</span><strong>${money(lateOrders)}</strong><small>${number(latePercent)}%</small></div></a>
  </div>
  ${noProductionDateOrders ? `<div class="production-missing">Без повних даних про строки: <b>${money(noProductionDateOrders)}</b></div>` : ''}
</section>`;

const yearCards = years.map((item, index) => `<article class="year-card ${index === years.length - 1 ? 'active' : ''}">
  <div class="year-label">${escapeHtml(item.Year)} YTD</div>
  <strong>${money(item.TotalAmount)} ₴</strong>
  <small>${money(item.OrdersCount)} зам. · ${money(item.ShippedQuantity)} констр.</small>
  ${growth(item.GrowthPercent)}
</article>`).join('');

const monthRows = months.map(item => `<tr>
  <td><b>${monthLabel(item.Month)}</b></td>
  <td class="num">${money(item.TotalAmount)} ₴</td>
  <td class="num">${money(item.OrdersCount)}</td>
  <td class="num">${money(item.ShippedQuantity)}</td>
  <td class="num">${growth(item.GrowthPercent)}</td>
</tr>`).join('');

const lastReportMonth = months.at(-1)?.Month ?? String(report.DateTo).slice(0, 7);
const [categoryYear, lastMonthNumber] = String(lastReportMonth).split('-').map(Number);
const categoryMonthKeys = Array.from(
  { length: lastMonthNumber },
  (_, index) => `${categoryYear}-${String(index + 1).padStart(2, '0')}`
);
const categoryYearRows = categoryMonths.filter(
  item => String(item.Month).startsWith(`${categoryYear}-`)
);
const categoryNames = [...new Set(categoryYearRows.map(item => item.Name))];
const categoryComparison = categoryNames.map(name => {
  const sourceValues = categoryYearRows.filter(item => item.Name === name);
  const sourceByMonth = new Map(sourceValues.map(item => [item.Month, item]));
  const values = categoryMonthKeys.map((month, index) => {
    const item = sourceByMonth.get(month) ?? {
      Name: name,
      Month: month,
      TotalAmount: 0,
      Quantity: 0,
      OrdersCount: 0,
    };
    const previous = index > 0
      ? Number(sourceByMonth.get(categoryMonthKeys[index - 1])?.TotalAmount || 0)
      : null;
    const currentAmount = Number(item.TotalAmount || 0);
    return {
      ...item,
      GrowthPercent: previous === null || previous === 0
        ? null
        : (currentAmount - previous) * 100 / previous,
    };
  });
  const current = values.at(-1) ?? {};
  const historyRows = values.map(item => `<div class="category-month">
    <div class="category-month-name">${monthLabel(item.Month)}</div>
    <div class="category-month-amount">${money(item.TotalAmount)} ₴</div>
    <div class="category-month-meta">
      <span>${money(item.Quantity)} шт.</span>
      ${growth(item.GrowthPercent)}
    </div>
  </div>`).join('');
  return `<details class="nested">
    <summary><span>${escapeHtml(name)}</span><small>${money(current.TotalAmount)} ₴ · ${growth(current.GrowthPercent)}</small><i>›</i></summary>
    <div class="category-history">${historyRows}</div>
  </details>`;
}).join('');

const totalTypeQty = types.reduce((sum, item) => sum + Number(item.Quantity || 0), 0);
const typeCards = types.map((item, index) => {
  const percent = pct(item.Quantity, totalTypeQty);
  return `<div class="mix-card">
    <div class="mix-top"><span class="dot c${index % 5}"></span><b>${escapeHtml(item.Name)}</b></div>
    <strong>${money(item.Quantity)}</strong>
    <span>${percent.toFixed(1)}% · ${money(item.OrdersCount)} зам.</span>
    <div class="mix-line"><i class="c${index % 5}" style="width:${percent}%"></i></div>
  </div>`;
}).join('');

const orderRows = orders.map(item => `<tr>
  <td><b>${escapeHtml(item.OrderNumber)}</b><small>${escapeHtml(item.ClientOrderNumber)}</small></td>
  <td>${escapeHtml(item.ContractorName)}</td>
  <td>${date(item.LastShipmentDate)}</td>
  <td class="num">${money(item.ConstructionsCount)}</td>
  <td class="num">${money(item.TotalAmount)} ₴</td>
  <td><span class="badge ${item.ShipmentCompleteness === 'Повністю' ? 'ok' : 'warn'}">${escapeHtml(item.ShipmentCompleteness)}</span></td>
</tr>`).join('');

